#include "Epidemic/GameFramework/Loot/loot.h"
using namespace epidemic;using namespace epidemic::gameplay;using namespace epidemic::gameplay::loot;
namespace {class Handler final:public IRewardHandler{public:std::int64_t delivered=0;[[nodiscard]]RewardTypeId Type()const noexcept override{return RewardTypeId::FromString("test.reward");}[[nodiscard]]foundation::Result<RewardDeliveryDisposition> Validate(const RewardOperation&)const override{return foundation::Result<RewardDeliveryDisposition>::Success(RewardDeliveryDisposition::Delivered);}[[nodiscard]]foundation::Result<RewardDeliveryDisposition> Deliver(const RewardOperation&o)override{delivered+=o.quantity_micro;return foundation::Result<RewardDeliveryDisposition>::Success(RewardDeliveryDisposition::Delivered);}};}
int main(){Handler h;LootService s;if(!s.RegisterRewardHandler("test.reward",&h))return 1;RewardDefinition r;r.canonical_name="test.reward.gold";r.type=h.Type();r.min_quantity_micro=10;r.max_quantity_micro=20;auto rid=s.RegisterRewardDefinition(r);if(!rid)return 2;LootTableDefinition t;t.canonical_name="test.table";t.policy=LootRollPolicy::GuaranteedAll;t.entries.push_back({LootEntryId::FromString("test.entry"),1,1'000'000,rid.Value(),{}, {}});auto tid=s.RegisterLootTable(t);if(!tid||!s.Freeze())return 3;GameplayObjectRef recipient{GameplayDomainId::FromString("test"),GameplayObjectId::FromString("player")};LootContext c;c.recipient=recipient;c.seed={42};auto a=s.Generate(tid.Value(),c);if(!a||a.Value().rewards.size()!=1)return 4;const auto quantity=a.Value().rewards[0].quantity_micro;LootService s2;Handler h2;auto h2r=s2.RegisterRewardHandler("test.reward",&h2);auto r2=s2.RegisterRewardDefinition(r);auto t2=s2.RegisterLootTable(t);auto f2=s2.Freeze();if(!h2r||!r2||!t2||!f2)return 5;auto b=s2.Generate(tid.Value(),c);if(!b||b.Value().rewards[0].quantity_micro!=quantity)return 5;auto pending=s.MakePending(std::move(a).Value());if(!pending||!s.Claim(pending.Value())||!s.WasClaimed(pending.Value()))return 6;const auto delivered=h.delivered;if(!s.Claim(pending.Value())||h.delivered!=delivered)return 7;return 0;}
